    {
        System.out.print(" MyThread");
    }
    public void run()
    {
        System.out.print(" Running");
    }
    public void run(String s)
    {
        System.out.println(" Running "+s);
    }
}
public class Test
{
    public static void main (String [] args)
    {
        Thread t = new MyThread()
        {
            public void run()
            {
                System.out.println(" Walking");
            }
        };
        t.start();
    }
}
```

